<template>
  <Card v-if="data" class="col-span-2 xl:col-span-1">
    <CardHeader v-if="data.title">
      <CardTitle>{{ data.title }}</CardTitle>
    </CardHeader>
    <CardContent v-if="loading || error">
      <AppLoader v-if="loading" variant="inline" subject="branch information" />
      <AppError
        v-else-if="error"
        class="col-span-2"
        title="Failed to load branch information"
        :message="props.error"
        variant="table"
      />
    </CardContent>
    <template v-else-if="data && !loading && !error">
      <CardContent>
        <EarningsBranchStatusContent :status="props.status" />
      </CardContent>
      <CardFooter class="flex-wrap gap-2">
        <NuxtLink v-if="data.transactionsButton && props.transactionsButton" :to="{ name: 'earnings-transactions' }">
          <Button variant="outline">Transactions History</Button>
        </NuxtLink>
        <a :href="data.branchUrl" target="_blank" rel="noopener noreferrer">
          <Button :prepend-icon="LinkIcon" variant="outline" @click="() => $emit('openBranchCallback')"
            >Open Branch</Button
          >
        </a>
      </CardFooter>
    </template>
  </Card>
</template>

<script setup lang="ts">
import { LinkIcon } from 'lucide-vue-next';
import type { PaymentAccountStatus } from '~/client';
import { getBranchDataByStatus } from '~/constants/earnings/branchData';

interface Props {
  status: PaymentAccountStatus;
  onboardingLink?: string | null;
  transactionsButton?: boolean;
  loading?: boolean;
  error?: string;
}

const props = withDefaults(defineProps<Props>(), {
  onboardingLink: null,
  transactionsButton: true,
  loading: false,
  error: undefined,
});

interface Emits {
  (e: 'openBranchCallback'): void;
}

defineEmits<Emits>();

const data = computed(() => {
  return getBranchDataByStatus(props.status, props.onboardingLink);
});
</script>
