import { getPaymentAccountDetails } from '~/client';

export const useEarnings = defineQuery(() => {
  const { isCanvasser } = useUserRole();
  const {
    data: earnings,
    error,
    isLoading,
    refetch,
  } = useQuery({
    key: () => ['earnings'],
    query: () => getPaymentAccountDetails({ composable: '$fetch' }),
    staleTime: 500, // infinite loop if set to 0
    enabled: () => isCanvasser.value,
  });

  return {
    earnings,
    error,
    isLoading,
    refetch,
  };
});
